  function openTreasurySheet(item=null,forcedType='income'){
    const type=item?.entry_type||forcedType;openSheet(`<form id="mTreasuryForm" class="m-sheet-form"><div class="m-sheet-handle"></div><header><span>${item?'修改账目':'新增账目'}</span><h2>${type==='income'?'收入':'支出'}</h2></header><label>类型<select name="entry_type"><option value="income" ${type==='income'?'selected':''}>收入</option><option value="expense" ${type==='expense'?'selected':''}>支出</option></select></label><label>金额<input name="amount" type="number" min="0.01" step="0.01" inputmode="decimal" value="${safe(item?.amount||'')}"/></label><label>说明<input name="reason" value="${safe(item?.reason||'')}"/></label><footer><button class="m-secondary" data-sheet-close type="button">取消</button>${item?'<button class="m-danger" data-m-money-delete type="button">删除</button>':''}<button class="m-primary" type="submit">保存</button></footer></form>`);
    document.querySelector('#mTreasuryForm')?.addEventListener('submit',async event=>{event.preventDefault();const fd=new FormData(event.currentTarget);const body={entry_type:fd.get('entry_type'),amount:fd.get('amount'),reason:fd.get('reason'),occurred_at:item?.occurred_at||new Date().toISOString()};try{await liveApi(item?`/api/treasury/entries/${item.entry_id}`:'/api/treasury/entries',{method:item?'PUT':'POST',body:JSON.stringify(body)});closeSheet();M.cache.clear();await navigate('treasury',false)}catch(error){liveNotice(error.message,true)}});
    document.querySelector('[data-m-money-delete]')?.addEventListener('click',async()=>{if(!confirm('确定删除这笔账吗？后台会保留历史快照。'))return;try{await liveApi(`/api/treasury/entries/${item.entry_id}`,{method:'DELETE',body:JSON.stringify({confirm_entry_id:item.entry_id})});closeSheet();M.cache.clear();await navigate('treasury',false)}catch(error){liveNotice(error.message,true)}});
  }

  async function renderBehavior(){
    const data=await api('/api/behavior/actions?limit=80',{sent_items:[],decisions:[],trajectory:{}});const sent=data.sent_items||[];const decisions=data.decisions||[];const trace=data.trajectory||{};const drivers=trace.emotion_drivers||[];
    const driverText=drivers.slice(0,6).map(item=>`${item.name} ${num(item.value).toFixed(2)}`).join(' · ')||'当前没有明显牵动';
    stage().innerHTML=`<section class="m-behavior"><div class="m-push-journey"><span>这一轮进行到哪里</span><h2>${safe(trace.phase_label||'等待新一轮')}</h2><p>${safe(trace.phase_detail||'')}</p><ol><li><i></i><div><small>本轮触发</small><strong>${safe(trace.trigger_summary||'本轮没有单独的文字写入')}</strong><time>${safe(time({created_at:trace.last_activity_at}))}</time></div></li><li><i></i><div><small>30分钟候静默</small><strong>${trace.phase==='active'?'正在重新计时':'已经完整结束'}</strong>${trace.silence_due_at?`<time>${safe(time({created_at:trace.silence_due_at}))}</time>`:''}</div></li><li><i></i><div><small>${num(trace.pipe_count)||48}项情绪参与判断</small><strong>${safe(driverText)}</strong></div></li><li><i></i><div><small>DeepSeek判断</small><strong>${safe(trace.phase_label||'等待判断')}</strong>${trace.next_review_at?`<time>下次复核 ${safe(time({created_at:trace.next_review_at}))}</time>`:''}</div></li></ol></div><div class="m-section-head"><div><span>已经送达</span><h2>${sent.length} 条推送</h2></div></div><div class="m-sent-list">${sent.map(item=>`<article><time>${safe(time(item))}</time><span>${safe(item.status_label||'已推送')}</span><strong>${safe(item.display_content||text(item)||'已完成一次推送')}</strong>${item.trigger_summary?`<p>因为：${safe(item.trigger_summary)}</p>`:''}${item.display_reason?`<p>${safe(item.display_reason)}</p>`:''}</article>`).join('')||empty('最近没有已发送的推送')}</div><details class="m-decisions"><summary>为什么没发、等待或取消 <b>${decisions.length}</b></summary>${decisions.map(item=>`<article><time>${safe(time(item))}</time><strong>${safe(item.status_label||'未发送')}</strong>${item.trigger_summary?`<p>本轮写入：${safe(item.trigger_summary)}</p>`:''}<p>${safe(item.display_reason||'本次没有发送')}</p>${item.next_review_at?`<p>下次复核：${safe(time({created_at:item.next_review_at}))}</p>`:''}</article>`).join('')||empty('没有未发送记录')}</details></section>`;
  }
  async function renderResonance(){const data=await api('/api/xinchao/resonance',{links:[],pull:{},hold:{}});const links=data.links||data.items||[];stage().innerHTML=`<section class="m-resonance"><div class="m-balance"><div><span>此刻的牵引</span><strong>${safe(data.pull?.name||data.strongest?.name||'平静')}</strong><b>${num(data.pull?.value||data.strongest?.value).toFixed(2)}</b></div><i></i><div><span>正在平衡</span><strong>${safe(data.hold?.name||data.counterweight?.name||'平衡')}</strong><b>${num(data.hold?.value||data.counterweight?.value).toFixed(2)}</b></div></div>${links.map(item=>`<article><strong>${safe(item.source_name||item.name||'一次记忆回响')}</strong><p>${safe(item.trigger||item.excerpt||item.why||'')}</p><small>${safe(item.why||'')}</small></article>`).join('')||empty('这一次还没有唤起明显的记忆回响')}</section>`;}
  async function renderPersonality(){const data=await api('/api/disposition?days=30',{tendency:{name:'仍在形成',score:0,delta:0},evidence:[]});const composite=data.composite||{};const tendency=composite.primary||data.tendency||data.current||{};const evidence=tendency.evidence||data.evidence||data.items||data.formation_path||[];const supporting=composite.supporting||((data.tendencies||[]).slice(1,4));const observing=composite.observing||data.observing||[];const effectText=item=>Object.entries(item.effects||item.deltas||{}).map(([name,value])=>`${name} ${num(value)>=0?'+':''}${num(value).toFixed(2)}`).join(' · ');const evidenceMarkup=items=>items?.length?items.map(item=>`<article><time>${safe(time(item))}</time><i></i><div><small>${safe(item.source_label||item.source||'一次经历')}</small><strong>${safe(title(item,'一条重复证据'))}</strong><p>${safe(item.reason||text(item)||item.summary||'')}</p><span>${safe(effectText(item))}</span></div></article>`).join(''):empty('还没有足够的重复证据');const traitCard=item=>`<article class="m-trait-card"><header><div><small>${safe(item.kind==='emerging_trace'?'观察中':'共同形成')}</small><strong>${safe(item.label||item.name||'未命名倾向')}</strong></div><b>${num(item.strength).toFixed(2)}</b></header><p>${safe(item.behavior_rule||'只在相似情境下作为软倾向参考。')}</p><time>最近出现：${safe(time({created_at:item.last_seen}))}</time><small>${num(item.evidence_count)} 条证据</small>${item.evidence?.length?`<details><summary>查看具体证据</summary><div class="m-trait-evidence">${evidenceMarkup(item.evidence)}</div></details>`:''}</article>`;stage().innerHTML=`<section class="m-personality"><div class="m-personality-hero"><span>近 30 天形成的主倾向</span><h2>${safe(tendency.name||tendency.label||'仍在形成')}</h2><strong>${num(tendency.score??tendency.strength).toFixed(2)}</strong><p>${safe(tendency.description||'')}</p></div><section class="m-composite-summary"><span>复合性格画像</span><p>${safe(composite.summary||'性格不是单一标签，而是多种反复倾向共同形成。')}</p></section>${supporting.length?`<section class="m-trait-section"><h2>同时存在的倾向</h2>${supporting.map(traitCard).join('')}</section>`:''}${observing.length?`<section class="m-trait-section m-observing"><h2>正在观察中的新倾向 <small>${observing.length} 项</small></h2><p>这些内容已经记录，但还没有达到长期性格证据的门槛。</p>${observing.map(traitCard).join('')}</section>`:''}<section class="m-formation"><span>为什么会形成</span><p>${safe(data.formation_reason||tendency.reason||'需要在不同日子里反复出现相近的选择与感受，才会逐渐形成。')}</p></section><div class="m-evidence"><h2>主倾向的具体证据 <small>${num(tendency.evidence_count||data.evidence_count||evidence.length)} 条</small></h2>${evidenceMarkup(evidence)}</div></section>`;}
  async function renderCoordinates(){const fallback={dimensions:{time:{name:'时间脉络',score:.18,delta:0,reason:'等待新的写入'},relation:{name:'关系牵引',score:.18,delta:0,reason:'等待新的写入'},fact:{name:'事实演化',score:.18,delta:0,reason:'等待新的写入'},emotion:{name:'情绪回响',score:.18,delta:0,reason:'等待新的写入'},memory:{name:'记忆沉淀',score:.18,delta:0,reason:'等待新的写入'}},nodes:[]};const data=await api('/api/brain/context?limit=20',fallback);const dimensions=data.dimensions||fallback.dimensions;const nodes=data.nodes||data.items||[];stage().innerHTML=`<section class="m-coordinates"><div class="m-coordinate-intro"><span>五条心智通道</span><h2>心智经纬</h2><p>它显示一条写入怎样经过时间、关系、事实、情绪与记忆，再影响后续理解。</p></div><div class="m-coordinate-map">${Object.entries(dimensions).map(([key,value],index)=>{const score=clamp(value.score??value.value??0);const delta=num(value.delta??value.change);return `<div style="--axis:${index};--score:${score}"><i></i><span><strong>${safe(value.name||key)}</strong><small>${safe(value.reason||`${delta?`${delta>0?'上升':'回落'} ${Math.abs(delta).toFixed(2)}`:'正在回落'}`)}</small></span><b><em></em></b><output>${score.toFixed(2)}</output></div>`}).join('')}</div><h2>最近经过大脑的内容</h2>${nodes.map(item=>{const effects=effectText(item.effects);return `<article><span>${safe(item.source_label||item.source||'一次写入')} · ${safe(time(item))}</span><strong>${safe(title(item,'一条内容'))}</strong><p>${safe(item.reason||text(item))}</p><small>${safe((item.dimension_labels||item.dimensions||[]).join(' → '))}${effects?` · ${safe(effects)}`:''}</small></article>`}).join('')||empty('还没有新的跨模块轨迹')}</section>`;}

  async function renderMore(){const icons={thoughts:'pen-line',mind:'sparkles',resonance:'git-merge',darkflow:'moon',behavior:'send',personality:'route',coordinates:'brain',timeline:'milestone',tasks:'list-checks',treasury:'wallet-cards',search:'search',toolbox:'wrench',settings:'settings'};const sections=[['想法与表达',[['thoughts','念痕'],['mind','心念'],['darkflow','暗涌'],['behavior','行为与推送']]],['内在形成',[['resonance','内在牵引'],['personality','性格轨迹'],['coordinates','心智经纬']]],['管理与工具',[['timeline','事实时间线'],['tasks','未竟'],['treasury','AI 小金库'],['search','搜索与日期'],['toolbox','工具箱'],['settings','设置与安全']]]];stage().innerHTML=`<section class="m-more">${sections.map(([name,items])=>`<h2>${name}</h2><div>${items.map(([id,label])=>`<button data-m-route="${id}" type="button"><i data-lucide="${icons[id]}"></i><span><strong>${label}</strong><small>${{thoughts:'AI 当下真实写下的痕迹',mind:'闪念、执念与已放下',darkflow:'静默后机器形成的内在文字',behavior:'发送、取消、确认与判断原因',resonance:'当前真正影响行为的合力',personality:'长期倾向与重复证据',coordinates:'内容怎样经过大脑',timeline:'把同一事件连成变化节点',tasks:'由你或当前 AI 主动维护',treasury:'余额、收支与每一笔明细',search:'关键词、人物和日期一起找',toolbox:'按用途查看可调用能力',settings:'密码、底色与生成规则'}[id]}</small></span><b>›</b></button>`).join('')}</div>`).join('')}</section>`;}
  async function renderContinuity(){const data=await api('/api/continuity/status',{state:{},darkflow:{},latest_mailbox:null,pending_push:null});const state=data.state||{},darkflow=data.darkflow||{},pending=data.pending_push||{};const steps=[['最近一次窗口交接',data.latest_mailbox?time(data.latest_mailbox):'还没有交接'],['当前活动周期',state.cycle_state||state.status||'正在读取'],['暗涌状态',darkflow.status_label||darkflow.status||darkflow.reason||'当前没有暗涌'],['推送接续',pending.available?'有一条等待确认的推送':'当前没有待确认推送']];stage().innerHTML=`<section class="m-tool-detail"><div class="m-tool-intro"><i data-lucide="workflow"></i><div><small>真实接续链路</small><h2>窗口有没有接上</h2><p>这里直接读取信箱、活动周期、暗涌和推送的当前状态。</p></div></div><ol class="m-tool-steps">${steps.map(([label,value],index)=>`<li><b>${index+1}</b><span><small>${safe(label)}</small><strong>${safe(value)}</strong></span></li>`).join('')}</ol><button class="m-tool-open" data-m-route="behavior" type="button">查看完整行为与推送 <i data-lucide="arrow-right"></i></button></section>`;}

  async function renderHealth(){const checks=[['管理服务','/api/health'],['记忆文件与索引','/api/vault-health'],['跨模块接续','/api/continuity/status'],['48项内在状态','/api/xinchao/status']];const results=await Promise.all(checks.map(async([label,path])=>{try{const value=await liveApi(path);return{label,ok:true,note:path==='/api/xinchao/status'?`${Object.keys(value.pipes||{}).length} 项可读`:String(value.status||value.summary||'读取正常')}}catch(error){return{label,ok:false,note:error.message||'读取失败'}}}));const passed=results.filter(item=>item.ok).length;stage().innerHTML=`<section class="m-tool-detail"><div class="m-health-score"><small>刚刚完成只读检查</small><strong>${passed}/${results.length}</strong><span>${passed===results.length?'全部正常':'有项目需要检查'}</span></div><div class="m-health-list">${results.map(item=>`<article class="${item.ok?'ok':'bad'}"><i data-lucide="${item.ok?'check-circle-2':'circle-alert'}"></i><span><strong>${safe(item.label)}</strong><small>${safe(item.note)}</small></span></article>`).join('')}</div><button class="m-tool-open" data-m-health-refresh type="button">重新检查 <i data-lucide="refresh-cw"></i></button></section>`;stage().querySelector('[data-m-health-refresh]')?.addEventListener('click',()=>{M.cache.clear();navigate('health',false)});}

  async function renderToolbox(){const groups=[['读取',[['搜索与浮现','search','按关键词、人物、日期和范围寻找真实内容。','search'],['读取原文','file-text','进入搜索并打开结果原文。','search'],['事实时间','calendar-days','查看同一事件怎样沿时间发生变化。','timeline'],['主题目录','folder-tree','进入主目录、子目录和单条记忆。','memory']]],['写入',[['记一件事','circle-plus','直接打开新增记忆表单。','memory','new-memory'],['归档并留言','archive','进入固定记忆库查看和修改归档。','memory'],['写信箱','mail-plus','进入信箱查看窗口交接。','mailbox'],['记录念痕','pen-line','进入 AI 当下真实写下的念痕。','thoughts']]],['状态',[['查看内在','heart-pulse','打开 48 项当前值、底色、来源和回落。','hormones'],['查看性格轨迹','route','打开近 30 天性格倾向与具体证据。','personality'],['查看连续性','workflow','读取信箱、暗涌和推送的接续状态。','continuity'],['查看行为与推送','send','查看发送、等待、取消和确认过程。','behavior']]],['管理',[['未竟','list-checks','打开可新增、修改和完成的未竟事项。','tasks'],['小金库','wallet-cards','打开余额、收入、支出和每一笔明细。','treasury'],['反馈检索','message-square-more','进入智能搜索查找纠正与反馈。','search'],['全库健康','shield-check','立即执行真实只读健康检查。','health']]]];stage().innerHTML=`<section class="m-toolbox">${groups.map(([name,items])=>`<section><h2>${name}</h2>${items.map(([label,icon,description,target,action])=>`<button data-m-tool="${safe(label)}" data-m-tool-route="${target}" data-m-tool-action="${action||''}" type="button"><i data-lucide="${icon}"></i><span><strong>${label}</strong><small>${safe(description)}</small></span><i data-lucide="chevron-right"></i></button>`).join('')}</section>`).join('')}</section>`;stage().querySelectorAll('[data-m-tool]').forEach(button=>button.addEventListener('click',async()=>{const target=button.dataset.mToolRoute;if(button.dataset.mToolAction==='new-memory'){await navigate('memory');openCreateMemorySheet();return}navigate(target)}));}
  async function renderSearch(){stage().innerHTML=`<section class="m-search-page"><form id="mSearchForm"><label>关键词<input id="mSearchInput" name="q" placeholder="一句话、一个事实或片段"/></label><label>人物<input name="person" placeholder="例如：菜菜"/></label><label>日期<input name="date" type="date"/></label><label>范围<select name="source"><option value="all">全部</option><option value="memory">记忆</option><option value="mailbox">信箱</option><option value="thoughts">念痕与心念</option></select></label><button type="submit">开始寻找</button></form><div id="mSearchResults">${empty('关键词、人物、日期，填写任意一项即可')}</div></section>`;document.querySelector('#mSearchForm')?.addEventListener('submit',async event=>{event.preventDefault();const fd=new FormData(event.currentTarget);const params=new URLSearchParams({q:String(fd.get('q')||'').trim(),person:String(fd.get('person')||'').trim(),date:String(fd.get('date')||''),source:String(fd.get('source')||'all'),limit:'80'});if(!params.get('q')&&!params.get('person')&&!params.get('date'))return;const data=await api(`/api/search?${params.toString()}`,{items:[]},true);const items=data.items||[];document.querySelector('#mSearchResults').innerHTML=`<p class="m-search-count">找到 ${items.length} 条</p>`+(items.map(item=>`<article class="m-record"><button type="button"><time>${safe(time(item))}</time><span>${safe(item.source==='mailbox'?'信箱':item.source==='thought'?'念痕与心念':'记忆')}</span><strong>${safe(title(item,'搜索结果'))}</strong><p>${safe(text(item))}</p></button></article>`).join('')||empty('没有找到匹配内容'))});}
