          form?.addEventListener('submit',async event=>{event.preventDefault();if(M.nurserySending)return;const message=String(new FormData(form).get('message')||'').trim();if(!message)return;const button=form.querySelector('[type="submit"]');const input=form.querySelector('[name="message"]');M.nurserySending=true;if(button)button.disabled=true;const pending={message,reply:'',pending:true,caregiver_display_name:'你',created_at:new Date().toISOString()};M.nurseryTurns=[...M.nurseryTurns,pending].slice(-30);if(input)input.value='';renderTurns();try{const latest=await readChild();if(String(latest.module_state||'')!=='active')throw new Error('房间状态已经改变；请重新打开后再操作。');const operationId=id();const result=await liveApi(`/api/nursery/children/${encodeURIComponent(childId)}/interactions`,{method:'POST',body:JSON.stringify({message,operation_id:operationId,idempotency_key:operationId,expected_state_version:num(latest.state_version)})});const operation=result.operation||{};const reply=String(operation.interaction?.reply||'').trim();if(operation.status!=='completed'||!reply)throw new Error(operation.error?.message||'这次没有得到可以展示的回复。');const care=operation.interaction?.care||null;M.nurseryTurns=M.nurseryTurns.map(turn=>turn===pending?{message,reply,caregiver_display_name:'你',created_at:new Date().toISOString()}:turn);renderTurns();const outcome=stage().querySelector('#mNurseryInteractionOutcome');if(outcome){const changes=careChange(care);outcome.textContent=care?.summary?`${care.summary}${changes.length?` · ${changes.join('，')}`:''}${care.world_item_id?' · 已放进房间':''}`:'';}}catch(error){M.nurseryTurns=M.nurseryTurns.filter(turn=>turn!==pending);renderTurns();if(input)input.value=message;liveNotice(userFacingError(error),true)}finally{M.nurserySending=false;if(button)button.disabled=false;}});
