        stage().querySelector('#mNurseryGrowthObservation')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const data=new FormData(form);const abilityId=String(data.get('ability_id')||'').trim();const behavior=String(data.get('observed_behavior')||'').trim();const assistance=String(data.get('assistance')||'').trim();if(!abilityId||!behavior||!assistance){liveNotice('请把这次看见的事和当时的帮助写完整。',true);return;}const button=form.querySelector('[type="submit"]');if(button)button.disabled=true;try{await submitFeature('record_growth_observation',{observation:{session_id:`mobile:${new Date().toISOString()}`,ability_ids:[abilityId],observed_behavior:behavior,assistance}});M.nurseryPage='growth';liveNotice('成长观察已经保存；它不会自动改变阶段。');await rerender();}catch(error){liveNotice(error.message,true)}finally{if(button)button.disabled=false}});
