      const renderMorePage=view=>{const settings=view.settings_view||{};const caregivers=Array.isArray(settings.caregivers)?settings.caregivers:[];const model=settings.model||{};const companionNames=caregivers.filter(item=>item.role==='external_ai_guardian').map(item=>item.display_name||'一位共同养育者');return `<section class="m-nursery-secondary"><section class="m-nursery-section"><h2>慢慢照看这一间房</h2><div class="m-nursery-list"><button data-nursery-page="conversation-user" type="button"><strong>我和${safe(childName)}</strong><span>我的对话与陪伴</span><b>›</b></button><button data-nursery-page="conversation-external" type="button"><strong>${safe(companionNames.join('、')||'共同养育者')}和${safe(childName)}</strong><span>查看实际发生的孩子对话</span><b>›</b></button><button data-nursery-page="shared-care" type="button"><strong>一起照顾${safe(childName)}</strong><span>查看双方已经做过的事</span><b>›</b></button><button data-nursery-page="family" type="button"><strong>共同日常与约定</strong><span>接着玩、留提醒、记下相处</span><b>›</b></button><button data-nursery-page="growth" type="button"><strong>关于${safe(childName)}</strong><span>资料、成长记录和阶段</span><b>›</b></button><button data-nursery-page="care" type="button"><strong>健康与照料</strong><span>${safe(attention?'有需要继续留意的记录':'查看已经保存的照料记录')}</span><b>›</b></button><button data-nursery-page="settings" type="button"><strong>连接与设置</strong><span>${safe(model.connection_status==='ready'?'孩子的回应模型已连接':'查看回应模型和联动状态')}</span><b>›</b></button></div></section><section class="m-nursery-section"><h2>养育者</h2><p class="m-nursery-intro">${safe(caregivers.length?caregivers.map(item=>item.display_name||'一位养育者').join('、'):'还没有可展示的养育者资料。')}</p></section></section>${nav('more')}`;};
